// Shapes the app works with. These are independent of the database, so pages
// and services never see raw database rows.

export type Tank = {
  id: string
  name: string
  site: string
  latitude: number
  longitude: number
  capacityLitres: number
  roofAreaM2: number
}

// What the dashboard's "Add tank" form submits. The id is generated by the
// store (see lib/services/slug.ts), not chosen by the person filling it in.
export type NewTank = {
  name: string
  site: string
  latitude: number
  longitude: number
  capacityLitres: number
  roofAreaM2: number
}

export type TankReading = {
  tankId: string
  recordedAt: Date
  levelPercent: number
  litresHarvested: number
  litresUsed: number
}

export type RainfallReading = {
  site: string
  recordedAt: Date
  rainfallMm: number
}

export type GreywaterStatus = 'ok' | 'filter_due' | 'fault'

export type GreywaterUnit = {
  id: string
  name: string
  site: string
  status: GreywaterStatus
  latitude: number
  longitude: number
}

// What the dashboard's "Add system" form submits. Status always starts 'ok'.
export type NewGreywaterUnit = {
  name: string
  site: string
  latitude: number
  longitude: number
}

export type GreywaterReading = {
  unitId: string
  recordedAt: Date
  litresCollected: number
  litresFiltered: number
  litresReused: number
  filterPressureKpa: number | null
}

// A separate type rather than making `id` required on GreywaterReading
// itself: every existing caller building one for insertGreywaterReadings
// (the simulator, the seed generator) never assigns an id. listGreywaterReadings()
// returns this; the edit/delete routes need a stable id to act on.
export type GreywaterReadingWithId = GreywaterReading & { id: number }

export const REPORT_CATEGORIES = {
  illegal_dumping: 'Illegal dumping',
  pollution_hotspot: 'Pollution hotspot',
  blocked_drainage: 'Blocked drainage',
  riverbank_degradation: 'Riverbank degradation',
  clean_up: 'Clean-up activity',
  restoration: 'Restoration activity',
} as const

export type ReportCategory = keyof typeof REPORT_CATEGORIES

export type RiverReport = {
  id: number
  category: ReportCategory
  description: string
  locationDescription: string
  latitude: number
  longitude: number
  // Up to MAX_REPORT_PHOTOS photos (see lib/data/types.ts).
  photoUrls: string[]
  reporterName: string | null
  status: 'open' | 'verified' | 'resolved'
  createdAt: Date
}

export const MAX_REPORT_PHOTOS = 10

export type NewRiverReport = {
  category: ReportCategory
  description: string
  locationDescription: string
  latitude: number
  longitude: number
  photoUrls: string[]
  reporterName: string | null
}

// What the dashboard's report-edit form submits. Deliberately narrower than
// NewRiverReport: photos and coordinates stay as originally submitted, this
// only covers the fields someone would actually need to correct.
export type EditRiverReport = {
  category: ReportCategory
  description: string
  locationDescription: string
  reporterName: string | null
}

export type ActivityKind = 'training' | 'clean_up' | 'restoration' | 'household_adoption'

export const ACTIVITY_KIND_LABELS: Record<ActivityKind, string> = {
  clean_up: 'River clean-up',
  restoration: 'Restoration / tree planting',
  training: 'Training / sensitisation',
  household_adoption: 'Household adoption',
}

export const MAX_ACTIVITY_PHOTOS = 10

export type Activity = {
  id: number
  kind: ActivityKind
  title: string
  location: string
  description: string
  occurredOn: string
  youthCount: number
  householdsReached: number
  facilitiesCount: number
  treesPlanted: number
  participants: number
  wasteCollectedKg: number
  areaRestoredM2: number
  photoUrls: string[]
}

// What the "Log activity" form submits. The title is derived server-side
// from the kind and location, so the form doesn't need to ask for one.
export type NewActivity = {
  kind: ActivityKind
  location: string
  description: string
  occurredOn: string
  youthCount: number
  householdsReached: number
  treesPlanted: number
  participants: number
  wasteCollectedKg: number
  areaRestoredM2: number
  photoUrls: string[]
}

export type Stakeholder = {
  id: number
  name: string
  organisationType: 'government' | 'community' | 'school' | 'ngo' | 'business' | 'funder'
  role: string
  influence: number
  interest: number
  latitude: number | null
  longitude: number | null
}

export type Device = {
  id: string
  tankId: string
  keyHash: string
  lastSeenAt: Date | null
}

// General interest list: anyone who wants to be part of the programme, not
// tied to one specific offer (a tank, training, and so on).
export type WaitlistEntry = {
  id: number
  name: string
  place: string
  phone: string
  email: string | null
  photoUrl: string | null
  audioUrl: string | null
  createdAt: Date
}

export type NewWaitlistEntry = {
  name: string
  place: string
  phone: string
  email: string | null
  photoUrl: string | null
  audioUrl: string | null
}

// A person who can sign in to the dashboard. Nobody self-registers: an admin
// adds each row via `npm run team:add`. passwordHash is never the raw
// password, see lib/services/auth.ts.
export type TeamMember = {
  id: number
  email: string
  passwordHash: string
  name: string
  createdAt: Date
}

export type NewTeamMember = {
  email: string
  passwordHash: string
  name: string
}
